// ─── Types ────────────────────────────────────────────────────────────────────

interface RequestResult {
  id: number;
  status: 'success' | 'error';
  ttft: number;          // Time to First Token (ms)
  totalLatency: number;  // Total response time (ms)
  tokensGenerated: number;
  tokensPerSecond: number;
  error?: string;
  startTime: number;
  endTime: number;
}

interface StressTestConfig {
  concurrentRequests: number;
  totalRequests: number;
  maxTokens: number;
  temperature: number;
}

interface AggregatedResults {
  totalRequests: number;
  successfulRequests: number;
  failedRequests: number;
  successRate: number;
  totalTime: number;
  throughput: number;       // successful requests per second
  avgLatency: number;
  minLatency: number;
  maxLatency: number;
  p50Latency: number;
  p95Latency: number;
  p99Latency: number;
  avgTtft: number;
  minTtft: number;
  maxTtft: number;
  p50Ttft: number;
  p95Ttft: number;
  avgTokensPerSecond: number;
  totalTokens: number;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function percentile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  const idx = (p / 100) * (sorted.length - 1);
  const lower = Math.floor(idx);
  const upper = Math.ceil(idx);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (idx - lower);
}

function formatMs(ms: number): string {
  if (ms === 0) return '—';
  if (ms < 1000) return `${ms.toFixed(0)}ms`;
  return `${(ms / 1000).toFixed(2)}s`;
}

function computeAggregated(results: RequestResult[], totalTime: number): AggregatedResults {
  const successful = results.filter(r => r.status === 'success');
  const latencies = successful.map(r => r.totalLatency).sort((a, b) => a - b);
  const ttfts = successful.filter(r => r.ttft > 0).map(r => r.ttft).sort((a, b) => a - b);
  const tps = successful.filter(r => r.tokensPerSecond > 0).map(r => r.tokensPerSecond);

  return {
    totalRequests: results.length,
    successfulRequests: successful.length,
    failedRequests: results.length - successful.length,
    successRate: results.length > 0 ? (successful.length / results.length) * 100 : 0,
    totalTime,
    throughput: totalTime > 0 ? (successful.length / (totalTime / 1000)) : 0,
    avgLatency: latencies.length > 0 ? latencies.reduce((a, b) => a + b, 0) / latencies.length : 0,
    minLatency: latencies.length > 0 ? latencies[0] : 0,
    maxLatency: latencies.length > 0 ? latencies[latencies.length - 1] : 0,
    p50Latency: percentile(latencies, 50),
    p95Latency: percentile(latencies, 95),
    p99Latency: percentile(latencies, 99),
    avgTtft: ttfts.length > 0 ? ttfts.reduce((a, b) => a + b, 0) / ttfts.length : 0,
    minTtft: ttfts.length > 0 ? ttfts[0] : 0,
    maxTtft: ttfts.length > 0 ? ttfts[ttfts.length - 1] : 0,
    p50Ttft: percentile(ttfts, 50),
    p95Ttft: percentile(ttfts, 95),
    avgTokensPerSecond: tps.length > 0 ? tps.reduce((a, b) => a + b, 0) / tps.length : 0,
    totalTokens: successful.reduce((sum, r) => sum + r.tokensGenerated, 0),
  };
}

// Build histogram bins for a latency distribution chart
function buildHistogram(values: number[], binCount = 12): { range: string; count: number; mid: number }[] {
  if (values.length === 0) return [];
  const sorted = [...values].sort((a, b) => a - b);
  const min = sorted[0];
  const max = sorted[sorted.length - 1];
  if (min === max) return [{ range: formatMs(min), count: values.length, mid: min }];

  const binSize = (max - min) / binCount;
  const bins: { range: string; count: number; mid: number }[] = [];

  for (let i = 0; i < binCount; i++) {
    const lo = min + i * binSize;
    const hi = lo + binSize;
    const count = values.filter(v => v >= lo && (i === binCount - 1 ? v <= hi : v < hi)).length;
    bins.push({
      range: `${formatMs(lo)}`,
      count,
      mid: (lo + hi) / 2,
    });
  }
  return bins.filter(b => b.count > 0 || bins.indexOf(b) === 0 || bins.indexOf(b) === bins.length - 1);
}

// ─── Component ────────────────────────────────────────────────────────────────

interface StressTestPanelProps {
  apiConfig: {
    saarthiBaseUrl: string;
    saarthiModel: string;
    saarthiApiKey: string;
  };
  buildPrompt: () => Array<{ role: string; content: string }>;
}

const PRESET_CONFIGS = [
  { label: 'Light', concurrent: 1, total: 5, maxTokens: 100 },
  { label: 'Medium', concurrent: 5, total: 20, maxTokens: 100 },
  { label: 'Heavy', concurrent: 10, total: 50, maxTokens: 100 },
  { label: 'Extreme', concurrent: 25, total: 100, maxTokens: 100 },
];

export const StressTestPanel: React.FC<StressTestPanelProps> = ({ apiConfig, buildPrompt }) => {
  const [config, setConfig] = useState<StressTestConfig>({
    concurrentRequests: 5,
    totalRequests: 20,
    maxTokens: 100,
    temperature: 0.8,
  });

  const [isRunning, setIsRunning] = useState(false);
  const [liveResults, setLiveResults] = useState<RequestResult[]>([]);
  const [aggregated, setAggregated] = useState<AggregatedResults | null>(null);
  const [progress, setProgress] = useState({ completed: 0, total: 0 });
  const [showAdvancedConfig, setShowAdvancedConfig] = useState(false);
  const [selectedPreset, setSelectedPreset] = useState<string>('Medium');
  const [elapsedTime, setElapsedTime] = useState(0);

  const abortControllerRef = useRef<AbortController | null>(null);
  const resultsRef = useRef<RequestResult[]>([]);
  const nextIdRef = useRef(0);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const testStartRef = useRef(0);

  // Get a working prompt — fallback if sidebar isn't filled
  const getTestPrompt = useCallback(() => {
    try {
      const prompt = buildPrompt();
      if (prompt && prompt.length > 0 && prompt[0].content.trim().length > 50) {
        return prompt;
      }
    } catch { /* fallback below */ }

    return [{
      role: 'user',
      content: 'Provide a brief agricultural advisory for wheat farming in Maharashtra during January. Keep it concise.',
    }];
  }, [buildPrompt]);

  // Execute a single streaming request and measure metrics
  const executeRequest = useCallback(async (
    id: number,
    signal: AbortSignal,
  ): Promise<RequestResult> => {
    const startTime = performance.now();
    let ttft = 0;
    let tokensGenerated = 0;
    let firstTokenReceived = false;

    try {
      const response = await fetch(apiConfig.saarthiBaseUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: apiConfig.saarthiModel,
          messages: getTestPrompt(),
          stream: true,
          temperature: config.temperature,
          max_tokens: config.maxTokens,
        }),
        signal,
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`HTTP ${response.status}: ${errorText.slice(0, 200)}`);
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error('No response body');

      const decoder = new TextDecoder();

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n').filter(l => l.trim() !== '');

        for (const line of lines) {
          if (!line.startsWith('data: ')) continue;
          const data = line.slice(6);
          if (data === '[DONE]') continue;

          try {
            const sanitized = data
              .replace(/'/g, '"')
              .replace(/None/g, 'null')
              .replace(/True/g, 'true')
              .replace(/False/g, 'false');

            const parsed = JSON.parse(sanitized);
            const content = parsed.choices?.[0]?.delta?.content || '';

            if (content) {
              if (!firstTokenReceived) {
                ttft = performance.now() - startTime;
                firstTokenReceived = true;
              }
              tokensGenerated++;
            }
          } catch { /* skip unparseable chunks */ }
        }
      }

      const endTime = performance.now();
      const totalLatency = endTime - startTime;

      return {
        id,
        status: 'success',
        ttft,
        totalLatency,
        tokensGenerated,
        tokensPerSecond: totalLatency > 0 ? tokensGenerated / (totalLatency / 1000) : 0,
        startTime,
        endTime,
      };
    } catch (error: any) {
      return {
        id,
        status: 'error',
        ttft: 0,
        totalLatency: performance.now() - startTime,
        tokensGenerated: 0,
        tokensPerSecond: 0,
        error: error.name === 'AbortError' ? 'Cancelled' : (error.message || 'Unknown error'),
        startTime,
        endTime: performance.now(),
      };
    }
  }, [apiConfig, getTestPrompt, config.temperature, config.maxTokens]);

  // Run the full stress test
  const runTest = useCallback(async () => {
    if (isRunning) return;

    setIsRunning(true);
    setLiveResults([]);
    setAggregated(null);
    resultsRef.current = [];
    nextIdRef.current = 0;
    setProgress({ completed: 0, total: config.totalRequests });
    setElapsedTime(0);

    testStartRef.current = performance.now();
    abortControllerRef.current = new AbortController();
    const signal = abortControllerRef.current.signal;

    // Start elapsed timer
    timerRef.current = setInterval(() => {
      setElapsedTime(performance.now() - testStartRef.current);
    }, 100);

    // Worker function — each worker pulls tasks from a shared counter
    const worker = async () => {
      while (!signal.aborted) {
        const id = nextIdRef.current++;
        if (id >= config.totalRequests) break;

        const result = await executeRequest(id, signal);
        resultsRef.current = [...resultsRef.current, result];

        // Update UI (batch updates via ref copy)
        setLiveResults([...resultsRef.current]);
        setProgress({ completed: resultsRef.current.length, total: config.totalRequests });
      }
    };

    // Launch concurrent workers
    const workerCount = Math.min(config.concurrentRequests, config.totalRequests);
    const workers = Array(workerCount).fill(null).map(() => worker());

    await Promise.all(workers);

    // Finalize
    if (timerRef.current) clearInterval(timerRef.current);
    const totalTime = performance.now() - testStartRef.current;
    setElapsedTime(totalTime);

    const finalResults = resultsRef.current;
    setLiveResults(finalResults);
    setAggregated(computeAggregated(finalResults, totalTime));
    setIsRunning(false);
  }, [isRunning, config, executeRequest]);

  // Cancel the running test
  const cancelTest = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    if (timerRef.current) {
      clearInterval(timerRef.current);
    }
  }, []);

  // Apply a preset configuration
  const applyPreset = (presetLabel: string) => {
    const preset = PRESET_CONFIGS.find(p => p.label === presetLabel);
    if (preset) {
      setSelectedPreset(presetLabel);
      setConfig(prev => ({
        ...prev,
        concurrentRequests: preset.concurrent,
        totalRequests: preset.total,
        maxTokens: preset.maxTokens,
      }));
    }
  };

  // Derived chart data
  const successfulResults = liveResults.filter(r => r.status === 'success');
  const latencyChartData = successfulResults.map(r => ({
    request: `#${r.id + 1}`,
    latency: Math.round(r.totalLatency),
    ttft: Math.round(r.ttft),
  }));

  const latencyHistData = buildHistogram(successfulResults.map(r => r.totalLatency));
  const ttftHistData = buildHistogram(successfulResults.map(r => r.ttft), 8);

  const throughputOverTime = (() => {
    if (successfulResults.length < 2) return [];
    const baseTime = successfulResults[0]?.startTime ?? 0;
    const bucketSize = 1000; // 1 second buckets
    const maxTime = Math.max(...successfulResults.map(r => r.endTime)) - baseTime;
    const buckets: { time: string; count: number; cumulative: number }[] = [];
    let cumulative = 0;

    for (let t = 0; t <= maxTime; t += bucketSize) {
      const count = successfulResults.filter(
        r => (r.endTime - baseTime) >= t && (r.endTime - baseTime) < t + bucketSize
      ).length;
      cumulative += count;
      buckets.push({
        time: `${(t / 1000).toFixed(0)}s`,
        count,
        cumulative,
      });
    }
    return buckets;
  })();

  const progressPercent = progress.total > 0 ? (progress.completed / progress.total) * 100 : 0;

  // Summary cards data
  const cards = aggregated ? [
    {
      label: 'Total Requests',
      value: `${aggregated.totalRequests}`,
      sub: `${aggregated.successfulRequests} ok / ${aggregated.failedRequests} failed`,
      icon: Target,
      color: 'text-blue-600',
      bg: 'bg-blue-50',
      border: 'border-blue-200',
    },
    {
      label: 'Success Rate',
      value: `${aggregated.successRate.toFixed(1)}%`,
      sub: `${aggregated.successfulRequests} of ${aggregated.totalRequests}`,
      icon: aggregated.successRate >= 90 ? CheckCircle2 : AlertCircle,
      color: aggregated.successRate >= 90 ? 'text-emerald-600' : 'text-red-600',
      bg: aggregated.successRate >= 90 ? 'bg-emerald-50' : 'bg-red-50',
      border: aggregated.successRate >= 90 ? 'border-emerald-200' : 'border-red-200',
    },
    {
      label: 'Avg Latency',
      value: formatMs(aggregated.avgLatency),
      sub: `P50: ${formatMs(aggregated.p50Latency)} · P95: ${formatMs(aggregated.p95Latency)}`,
      icon: Clock,
      color: 'text-amber-600',
      bg: 'bg-amber-50',
      border: 'border-amber-200',
    },
    {
      label: 'Throughput',
      value: `${aggregated.throughput.toFixed(2)} req/s`,
      sub: `Total time: ${formatMs(aggregated.totalTime)}`,
      icon: TrendingUp,
      color: 'text-purple-600',
      bg: 'bg-purple-50',
      border: 'border-purple-200',
    },
    {
      label: 'Avg TTFT',
      value: formatMs(aggregated.avgTtft),
      sub: `P50: ${formatMs(aggregated.p50Ttft)} · P95: ${formatMs(aggregated.p95Ttft)}`,
      icon: Timer,
      color: 'text-cyan-600',
      bg: 'bg-cyan-50',
      border: 'border-cyan-200',
    },
    {
      label: 'Tokens/sec',
      value: `${aggregated.avgTokensPerSecond.toFixed(1)}`,
      sub: `Total tokens: ${aggregated.totalTokens}`,
      icon: Zap,
      color: 'text-orange-600',
      bg: 'bg-orange-50',
      border: 'border-orange-200',
    },
  ] : [];

  return (
    <div className="h-full overflow-y-auto scrollbar-thin p-6 bg-[#eef2f6]">
      <div className="max-w-7xl mx-auto space-y-6">

        {/* ─── Header ─────────────────────────────────────────────── */}
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-3">
              <Activity className="text-purple-600" size={28} />
              Model Stress Test
            </h2>
            <p className="text-sm text-slate-500 mt-1">
              Measure concurrent capacity, latency, TTFT, and throughput of <span className="font-medium text-slate-700">{apiConfig.saarthiModel}</span>
            </p>
          </div>
          {isRunning && (
            <div className="flex items-center gap-2 text-sm text-amber-600 bg-amber-50 px-4 py-2 rounded-lg border border-amber-200">
              <div className="w-2 h-2 bg-amber-500 rounded-full animate-pulse" />
              Test Running... {formatMs(elapsedTime)}
            </div>
          )}
        </div>

        {/* ─── Configuration ──────────────────────────────────────── */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-5">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                <Settings2 size={16} className="text-slate-500" />
                Test Configuration
              </h3>
              <button
                onClick={() => setShowAdvancedConfig(!showAdvancedConfig)}
                className="text-xs text-slate-500 hover:text-slate-700 flex items-center gap-1 transition-colors"
              >
                {showAdvancedConfig ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                Advanced
              </button>
            </div>

            {/* Presets */}
            <div className="flex gap-2 mb-4">
              {PRESET_CONFIGS.map((preset) => (
                <button
                  key={preset.label}
                  onClick={() => applyPreset(preset.label)}
                  disabled={isRunning}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                    selectedPreset === preset.label
                      ? 'bg-purple-600 text-white shadow-sm'
                      : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                  } ${isRunning ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  {preset.label}
                  <span className="block text-[10px] opacity-75 mt-0.5">
                    {preset.concurrent}x{preset.total}
                  </span>
                </button>
              ))}
            </div>

            {/* Config Fields */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <label className="text-xs font-medium text-slate-500 mb-1.5 block">
                  Concurrent Requests
                </label>
                <input
                  type="number"
                  min={1}
                  max={100}
                  value={config.concurrentRequests}
                  onChange={(e) => {
                    setSelectedPreset('');
                    setConfig(prev => ({ ...prev, concurrentRequests: parseInt(e.target.value) || 1 }));
                  }}
                  disabled={isRunning}
                  className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-purple-500/40 focus:border-purple-400 disabled:opacity-50"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-slate-500 mb-1.5 block">
                  Total Requests
                </label>
                <input
                  type="number"
                  min={1}
                  max={500}
                  value={config.totalRequests}
                  onChange={(e) => {
                    setSelectedPreset('');
                    setConfig(prev => ({ ...prev, totalRequests: parseInt(e.target.value) || 1 }));
                  }}
                  disabled={isRunning}
                  className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-purple-500/40 focus:border-purple-400 disabled:opacity-50"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-slate-500 mb-1.5 block">
                  Max Tokens
                </label>
                <input
                  type="number"
                  min={10}
                  max={5000}
                  value={config.maxTokens}
                  onChange={(e) => setConfig(prev => ({ ...prev, maxTokens: parseInt(e.target.value) || 100 }))}
                  disabled={isRunning}
                  className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-purple-500/40 focus:border-purple-400 disabled:opacity-50"
                />
              </div>
              {showAdvancedConfig && (
                <div>
                  <label className="text-xs font-medium text-slate-500 mb-1.5 block">
                    Temperature
                  </label>
                  <input
                    type="number"
                    min={0}
                    max={2}
                    step={0.1}
                    value={config.temperature}
                    onChange={(e) => setConfig(prev => ({ ...prev, temperature: parseFloat(e.target.value) || 0.8 }))}
                    disabled={isRunning}
                    className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-purple-500/40 focus:border-purple-400 disabled:opacity-50"
                  />
                </div>
              )}
            </div>

            {/* Run / Cancel Buttons */}
            <div className="flex items-center gap-3 mt-5">
              {isRunning ? (
                <button
                  onClick={cancelTest}
                  className="flex items-center gap-2 px-6 py-2.5 bg-red-600 hover:bg-red-700 text-white font-semibold rounded-lg transition-all shadow-sm"
                >
                  <Square size={16} />
                  Cancel Test
                </button>
              ) : (
                <button
                  onClick={runTest}
                  className="flex items-center gap-2 px-6 py-2.5 bg-purple-600 hover:bg-purple-700 text-white font-semibold rounded-lg transition-all shadow-sm"
                >
                  <Play size={16} />
                  Run Stress Test
                </button>
              )}

              <div className="text-xs text-slate-500">
                {config.concurrentRequests} concurrent &middot; {config.totalRequests} total requests &middot; {config.maxTokens} max tokens
              </div>
            </div>
          </div>

          {/* Progress Bar */}
          {(isRunning || progress.completed > 0) && (
            <div className="px-5 pb-4">
              <div className="flex items-center justify-between text-xs text-slate-500 mb-1.5">
                <span>Progress</span>
                <span>
                  {progress.completed} / {progress.total} ({progressPercent.toFixed(0)}%)
                </span>
              </div>
              <div className="w-full h-2.5 bg-slate-100 rounded-full overflow-hidden">
                <div
                  className={`h-full rounded-full transition-all duration-300 ${
                    isRunning ? 'bg-purple-500' : 'bg-emerald-500'
                  }`}
                  style={{ width: `${progressPercent}%` }}
                />
              </div>
              {/* Live mini-stats during run */}
              {isRunning && successfulResults.length > 0 && (
                <div className="flex gap-4 mt-2 text-xs text-slate-500">
                  <span>Avg latency: <b className="text-slate-700">{formatMs(successfulResults.reduce((s, r) => s + r.totalLatency, 0) / successfulResults.length)}</b></span>
                  <span>Avg TTFT: <b className="text-slate-700">{formatMs(successfulResults.reduce((s, r) => s + r.ttft, 0) / successfulResults.length)}</b></span>
                  <span>Errors: <b className={liveResults.filter(r => r.status === 'error').length > 0 ? 'text-red-600' : 'text-slate-700'}>{liveResults.filter(r => r.status === 'error').length}</b></span>
                </div>
              )}
            </div>
          )}
        </div>

        {/* ─── Results ────────────────────────────────────────────── */}
        {aggregated && (
          <>
            {/* Summary Cards */}
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
              {cards.map((card) => (
                <div
                  key={card.label}
                  className={`${card.bg} border ${card.border} rounded-xl p-4 transition-all hover:shadow-sm`}
                >
                  <div className="flex items-center gap-2 mb-2">
                    <card.icon size={16} className={card.color} />
                    <span className="text-xs font-medium text-slate-500">{card.label}</span>
                  </div>
                  <div className={`text-xl font-bold ${card.color}`}>{card.value}</div>
                  <div className="text-[11px] text-slate-500 mt-1">{card.sub}</div>
                </div>
              ))}
            </div>

            {/* Latency Percentiles Table */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
              <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2 mb-4">
                <Gauge size={16} className="text-amber-500" />
                Latency Percentiles
              </h3>
              <div className="grid grid-cols-7 gap-2">
                {[
                  { label: 'Min', value: aggregated.minLatency },
                  { label: 'P50', value: aggregated.p50Latency },
                  { label: 'P95', value: aggregated.p95Latency },
                  { label: 'P99', value: aggregated.p99Latency },
                  { label: 'Max', value: aggregated.maxLatency },
                  { label: 'Avg', value: aggregated.avgLatency },
                  { label: 'Std Dev', value: (() => {
                    const latencies = successfulResults.map(r => r.totalLatency);
                    const avg = latencies.reduce((a, b) => a + b, 0) / latencies.length;
                    return Math.sqrt(latencies.reduce((sum, l) => sum + (l - avg) ** 2, 0) / latencies.length);
                  })() },
                ].map(({ label, value }) => (
                  <div key={label} className="bg-slate-50 rounded-lg p-3 text-center">
                    <div className="text-[10px] font-medium text-slate-400 uppercase tracking-wider">{label}</div>
                    <div className="text-sm font-bold text-slate-800 mt-1">{formatMs(value)}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Charts Row */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">

              {/* Latency per Request */}
              <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2 mb-4">
                  <BarChart3 size={16} className="text-blue-500" />
                  Latency per Request
                </h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={latencyChartData}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                      <XAxis dataKey="request" tick={{ fontSize: 10 }} stroke="#94a3b8" />
                      <YAxis
                        tick={{ fontSize: 10 }}
                        stroke="#94a3b8"
                        tickFormatter={(v) => formatMs(v)}
                      />
                      <Tooltip
                        contentStyle={{
                          backgroundColor: '#fff',
                          border: '1px solid #e2e8f0',
                          borderRadius: '8px',
                          fontSize: '12px',
                        }}
                        formatter={(value: number | undefined, name: string | undefined) => [
                          formatMs(value ?? 0),
                          name === 'latency' ? 'Total Latency' : 'TTFT',
                        ]}
                      />
                      <Legend iconSize={10} wrapperStyle={{ fontSize: '11px' }} />
                      <Line
                        type="monotone"
                        dataKey="latency"
                        stroke="#6366f1"
                        strokeWidth={2}
                        dot={{ r: 2, fill: '#6366f1' }}
                        name="Total Latency"
                      />
                      <Line
                        type="monotone"
                        dataKey="ttft"
                        stroke="#06b6d4"
                        strokeWidth={2}
                        dot={{ r: 2, fill: '#06b6d4' }}
                        name="TTFT"
                      />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* Latency Distribution */}
              <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2 mb-4">
                  <BarChart3 size={16} className="text-purple-500" />
                  Latency Distribution
                </h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={latencyHistData}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                      <XAxis dataKey="range" tick={{ fontSize: 9 }} stroke="#94a3b8" angle={-30} textAnchor="end" height={50} />
                      <YAxis tick={{ fontSize: 10 }} stroke="#94a3b8" />
                      <Tooltip
                        contentStyle={{
                          backgroundColor: '#fff',
                          border: '1px solid #e2e8f0',
                          borderRadius: '8px',
                          fontSize: '12px',
                        }}
                        formatter={(value: number | undefined) => [`${value ?? 0} requests`, 'Count']}
                      />
                      <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                        {latencyHistData.map((_, index) => (
                          <Cell key={index} fill={index < latencyHistData.length * 0.5 ? '#a78bfa' : index < latencyHistData.length * 0.8 ? '#c084fc' : '#e879f9'} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* TTFT Distribution */}
              <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2 mb-4">
                  <Timer size={16} className="text-cyan-500" />
                  TTFT Distribution
                </h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={ttftHistData}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                      <XAxis dataKey="range" tick={{ fontSize: 9 }} stroke="#94a3b8" angle={-30} textAnchor="end" height={50} />
                      <YAxis tick={{ fontSize: 10 }} stroke="#94a3b8" />
                      <Tooltip
                        contentStyle={{
                          backgroundColor: '#fff',
                          border: '1px solid #e2e8f0',
                          borderRadius: '8px',
                          fontSize: '12px',
                        }}
                        formatter={(value: number | undefined) => [`${value ?? 0} requests`, 'Count']}
                      />
                      <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                        {ttftHistData.map((_, index) => (
                          <Cell key={index} fill={index < ttftHistData.length * 0.5 ? '#22d3ee' : index < ttftHistData.length * 0.8 ? '#67e8f9' : '#a5f3fc'} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* Throughput Over Time */}
              {throughputOverTime.length > 1 && (
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
                  <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2 mb-4">
                    <TrendingUp size={16} className="text-emerald-500" />
                    Throughput Over Time
                  </h3>
                  <div className="h-64">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={throughputOverTime}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                        <XAxis dataKey="time" tick={{ fontSize: 10 }} stroke="#94a3b8" />
                        <YAxis tick={{ fontSize: 10 }} stroke="#94a3b8" />
                        <Tooltip
                          contentStyle={{
                            backgroundColor: '#fff',
                            border: '1px solid #e2e8f0',
                            borderRadius: '8px',
                            fontSize: '12px',
                          }}
                        />
                        <Legend iconSize={10} wrapperStyle={{ fontSize: '11px' }} />
                        <Area
                          type="monotone"
                          dataKey="count"
                          stroke="#10b981"
                          fill="#d1fae5"
                          strokeWidth={2}
                          name="Completed/sec"
                        />
                        <Area
                          type="monotone"
                          dataKey="cumulative"
                          stroke="#6366f1"
                          fill="#e0e7ff"
                          strokeWidth={2}
                          name="Cumulative"
                        />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              )}
            </div>

            {/* ─── Detailed Results Table ─────────────────────────── */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="p-5 border-b border-slate-100">
                <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                  <Hash size={16} className="text-slate-500" />
                  Detailed Results ({liveResults.length} requests)
                </h3>
              </div>
              <div className="max-h-80 overflow-y-auto scrollbar-thin">
                <table className="w-full text-sm">
                  <thead className="sticky top-0 bg-slate-50 border-b border-slate-100">
                    <tr>
                      <th className="px-4 py-2.5 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">#</th>
                      <th className="px-4 py-2.5 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Status</th>
                      <th className="px-4 py-2.5 text-right text-xs font-medium text-slate-500 uppercase tracking-wider">TTFT</th>
                      <th className="px-4 py-2.5 text-right text-xs font-medium text-slate-500 uppercase tracking-wider">Total Latency</th>
                      <th className="px-4 py-2.5 text-right text-xs font-medium text-slate-500 uppercase tracking-wider">Tokens</th>
                      <th className="px-4 py-2.5 text-right text-xs font-medium text-slate-500 uppercase tracking-wider">Tokens/s</th>
                      <th className="px-4 py-2.5 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Error</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {liveResults
                      .sort((a, b) => a.id - b.id)
                      .map((result) => (
                        <tr
                          key={result.id}
                          className={`hover:bg-slate-50/50 transition-colors ${
                            result.status === 'error' ? 'bg-red-50/30' : ''
                          }`}
                        >
                          <td className="px-4 py-2 text-slate-600 font-mono text-xs">{result.id + 1}</td>
                          <td className="px-4 py-2">
                            {result.status === 'success' ? (
                              <span className="inline-flex items-center gap-1 text-emerald-600 text-xs font-medium">
                                <CheckCircle2 size={13} /> OK
                              </span>
                            ) : (
                              <span className="inline-flex items-center gap-1 text-red-600 text-xs font-medium">
                                <XCircle size={13} /> Error
                              </span>
                            )}
                          </td>
                          <td className="px-4 py-2 text-right font-mono text-xs text-slate-700">
                            {result.ttft > 0 ? formatMs(result.ttft) : '—'}
                          </td>
                          <td className="px-4 py-2 text-right font-mono text-xs text-slate-700">
                            {formatMs(result.totalLatency)}
                          </td>
                          <td className="px-4 py-2 text-right font-mono text-xs text-slate-700">
                            {result.tokensGenerated || '—'}
                          </td>
                          <td className="px-4 py-2 text-right font-mono text-xs text-slate-700">
                            {result.tokensPerSecond > 0 ? result.tokensPerSecond.toFixed(1) : '—'}
                          </td>
                          <td className="px-4 py-2 text-xs text-red-500 max-w-[200px] truncate">
                            {result.error || '—'}
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </table>
              </div>
            </div>
          </>
        )}

        {/* Empty State */}
        {!isRunning && !aggregated && liveResults.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="w-20 h-20 rounded-2xl bg-purple-50 border border-purple-200 flex items-center justify-center mb-6">
              <Activity size={36} className="text-purple-500" />
            </div>
            <h3 className="text-xl font-bold text-slate-800 mb-2">Ready to Stress Test</h3>
            <p className="text-sm text-slate-500 max-w-md mb-6">
              Configure the test parameters above and click "Run Stress Test" to measure
              concurrent capacity, latency, TTFT, and throughput of the model endpoint.
            </p>
            <div className="flex flex-wrap justify-center gap-3">
              {['Concurrent Capacity', 'Response Latency', 'Time to First Token', 'Throughput (req/s)', 'Token Generation Speed'].map((tag) => (
                <span key={tag} className="px-3 py-1.5 bg-white border border-slate-200 rounded-full text-xs text-slate-500">
                  {tag}
                </span>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default StressTestPanel;
